# 倍增 LCA: 预处理
LOG = ceil(log2(n))
for i in 0..LOG-1:
  for u in 0..n-1:
    up[u][i] = up[up[u][i-1]][i-1]  # 自底向上按 i 递推

# 查询 lca(u, v)
if depth[u] < depth[v]: swap(u, v)
d = depth[u] - depth[v]
for i in 0..LOG-1:
  if d & (1<<i): u = up[u][i]          # 二进制拆分抬升
if u == v: return u
for i in LOG-1..0:
  if up[u][i] != up[v][i]:             # 不同则一起跳
    u = up[u][i]; v = up[v][i]
return up[u][0]

